import{Z as t,e as n,f as o,a0 as i}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Zendesk","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/help-desk/zendesk.md","filePath":"integrations/help-desk/zendesk.md","lastUpdated":1780377007000}'),s={name:"integrations/help-desk/zendesk.md"};function a(r,e,l,h,d,c){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="zendesk" tabindex="-1">Zendesk <a class="header-anchor" href="#zendesk" aria-label="Permalink to &quot;Zendesk&quot;">​</a></h1><p>Connect Zendesk to send support enquiries to your help-desk account. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Help Desk</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Zendesk</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-zendesk-api" tabindex="-1">Step 2. Connect to the Zendesk API <a class="header-anchor" href="#step-2-connect-to-the-zendesk-api" aria-label="Permalink to &quot;Step 2. Connect to the Zendesk API&quot;">​</a></h3><ol><li>Go to <a href="https://www.zendesk.com" target="_blank">Zendesk</a> and log in to your account.</li><li>In the left-hand sidebar, click the <strong>Settings</strong> icon.</li><li>Click the <strong>Go to Admin Center</strong> link.</li><li>In the left-hand sidebar select <strong>Apps and Integrations</strong> → <strong>Zendesk API</strong>.</li><li>Ensure that <strong>Token Access</strong> is enabled.</li><li>Click the <strong>Add API Token</strong> button.</li><li>Copy the <strong>API Key</strong> from Zendesk and paste in the <strong>API Key</strong> field in Formie.</li><li>Enter the full domain (including <code>https://</code>) for your Zendesk account in the <strong>Domain</strong> field in Formie.</li><li>Enter your Zendesk <strong>login email</strong> (the same one used to generate the token) in the <strong>Username</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar to verify the connection.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination options offered by this integration and map required fields with the variable picker. For a support enquiry, map the visitor’s email and message where those fields are available.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the resulting enquiry in the selected account and check the sender details and submitted message.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const u=t(s,[["render",a]]);export{p as __pageData,u as default};
